target.css:
:root {
  --paper: #fffefa;
  --ink: #17352e;
  --muted: #647b73;
  --line: #d6e4dc;
  --mint: #dcf4e9;
  --teal: #167b67;
  --lime: #c7e968;
  --amber: #f2ba4c;
  --deep-teal: #0d5b4d;
}

.audit-card {
  box-sizing: border-box;
  width: 500px;
  max-width: 100%;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.audit-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 13px;
  border-bottom: 1px solid var(--line);
}

.title-block {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--teal);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 0;
  font-size: 23px;
  font-weight: 750;
  letter-spacing: -0.04em;
  line-height: 1;
}

.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 9px;
  color: var(--deep-teal);
  background: var(--lime);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 750;
  line-height: 1;
  text-transform: uppercase;
}

.status-dot {
  width: 7px;
  height: 7px;
  background: var(--deep-teal);
  border-radius: 50%;
}

.audit-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(145px, 0.85fr);
  gap: 12px;
  padding: 13px 0;
}

.check-panel {
  padding: 12px;
  background: var(--mint);
  border-radius: 12px;
}

.panel-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

h2 {
  margin-bottom: 0;
  font-size: 13px;
  font-weight: 750;
  line-height: 1.2;
}

time {
  color: var(--muted);
  font-size: 11px;
  line-height: 1;
  white-space: nowrap;
}

.check-list {
  display: grid;
  gap: 5px;
  padding: 0;
  margin: 0;
  list-style: none;
}

.check-list li {
  display: grid;
  grid-template-columns: 18px 1fr auto;
  align-items: center;
  gap: 7px;
  min-height: 25px;
  padding: 0 7px;
  background: var(--paper);
  border-radius: 7px;
  font-size: 12px;
}

.check-icon {
  display: grid;
  width: 16px;
  height: 16px;
  place-items: center;
  color: var(--paper);
  background: var(--teal);
  border-radius: 50%;
  font-size: 10px;
  font-weight: 800;
}

.check-label {
  color: var(--muted);
}

.check-list strong {
  color: var(--ink);
  font-size: 12px;
  font-weight: 750;
}

.score-panel {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 12px;
  background: var(--ink);
  border-radius: 12px;
}

.score-label {
  margin-bottom: 1px;
  color: var(--lime);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.07em;
  line-height: 1.2;
  text-transform: uppercase;
}

.score-number {
  color: var(--paper);
  font-size: 31px;
  font-weight: 750;
  letter-spacing: -0.06em;
  line-height: 1;
}

.score-number span {
  color: var(--mint);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0;
}

.score-note {
  margin: 6px 0 8px;
  color: var(--mint);
  font-size: 11px;
  line-height: 1.28;
}

.audit-meta {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin: 0;
}

.audit-meta div {
  padding-top: 6px;
  border-top: 1px solid var(--teal);
}

.audit-meta dt {
  color: var(--mint);
  font-size: 9px;
  line-height: 1.1;
  text-transform: uppercase;
}

.audit-meta dd {
  margin: 2px 0 0;
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
}

.audit-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.audit-footer p {
  margin-bottom: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.2;
}

.location-pin {
  color: var(--amber);
  font-size: 13px;
}

button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
  padding: 8px 10px;
  color: var(--paper);
  background: var(--teal);
  border: 0;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 750;
  line-height: 1;
}

button span {
  font-size: 15px;
  line-height: 0;
}

